            if(cnt==width){
              while(cnt--){W[i]=false;i--;}
               i++;
               cat[id]=[i,width];
               ans=i;
               break;
            }
         }
         console.log(ans);
      }
      if(sw[0]=="w"){
         var id=sw[1];
         var width=cat[id][1];
         var i=cat[id][0];
         while(width--){W[i]=true;i++;}
      }
   }
   console.log("END");
}

